@JvmName("step291")
fun step291(limit: Int): Int {
    var total = 0
    for (index in 1..limit) {
        total += index
    }
    return total + 98
}
sealed class Outcome292 {
    data class Success(val payload: String) : Outcome292()
    data object Failure : Outcome292()
}

fun describe292(outcome: Outcome292): String = when (outcome) {
    is Outcome292.Success -> outcome.payload
    Outcome292.Failure -> "failed"
}
